"""Independent point-array metric/SSE audit and compact plotting tables."""
from pathlib import Path
import argparse,json,sys
import numpy as np
import pandas as pd
HERE=Path(__file__).resolve().parent;OUT=HERE/'results'
def run(paths):
 c=json.loads(Path(paths).read_text(encoding='utf8'));records=[];summary=[];decomp=[];cases=[]
 for site in ['YULARA_COMBINED','NIST_GROUND']:
  # This explicit local artifact was generated by frozen_evaluation in this
  # task; its first version stores Pandas string timestamps as an object array.
  with np.load(Path(c['destination'])/site/'fixed_2018_predictions.npz',allow_pickle=True) as z:
   y=z['labels'];daily=z['Daily'];last=z['Last-value'];o=pd.DatetimeIndex(pd.to_datetime(z['forecast_origin'])).as_unit('ns');ts=z['target_timestamp_ns'];threshold=z['threshold']
   assert np.array_equal(ts,o.asi8[:,None]+np.arange(1,145)*300_000_000_000)
   df=pd.read_csv(OUT/(site+'_2018_Apr_Jun_origins_metrics.csv'))
   for r in df.itertuples():
    yy=y[:,:r.horizon];pp=z[r.method.replace(' ','_')][:,:r.horizon];mask=np.isfinite(yy)&np.isfinite(daily[:,:r.horizon])&np.isfinite(last[:,:r.horizon])
    if r.scope=='power-active':mask &= yy>threshold
    if r.scope=='low-power':mask &= yy<=threshold
    e=pp[mask].astype(float)-yy[mask].astype(float);values={'points':len(e),'origins':int(mask.any(1).sum()),'RMSE':np.sqrt(np.sum(e*e)/len(e)),'MAE':np.sum(abs(e))/len(e),'bias':np.sum(e)/len(e),'SSE':np.sum(e*e)}
    for key,v in values.items():assert np.isclose(v,getattr(r,key),rtol=1e-9,atol=1e-8),(site,r.method,key)
    records.append(dict(site=site,horizon=r.horizon,scope=r.scope,method=r.method,point_array_metric_agreement=True))
   for h in [12,48,96,144]:
    for scope in ['full','power-active','low-power']:
     part=df[(df.horizon==h)&(df.scope==scope)]
     for name,keys in [('Inverted mean',['Inverted42','Inverted43','Inverted44']),('Original A',['Original A']),('Original B',['Original B']),('Expanded A',['Expanded A']),('Expanded B',['Expanded B']),('Daily',['Daily']),('Last-value',['Last-value'])]:
      q=part[part.method.isin(keys)];summary.append(dict(site=site,period='2018_Apr_Jun_origins',horizon=h,scope=scope,method=name,RMSE=q.RMSE.mean(),RMSE_seed_SD=q.RMSE.std(ddof=1) if len(q)>1 else np.nan,MAE=q.MAE.mean(),bias=q.bias.mean(),points=int(q.points.iloc[0]),origins=int(q.origins.iloc[0])))
   for h in [12,48,96,144]:
    q=df[df.horizon==h].set_index(['method','scope']);total=q.loc[('Daily','full'),'points'];base=q.loc[('Daily','full'),'SSE']
    for name in ['Inverted42','Inverted43','Inverted44','Original B','Expanded B']:
     sums=[]
     for scope in ['power-active','low-power']:
      s=q.loc[(name,scope),'SSE'];ref=q.loc[('Daily',scope),'SSE'];v=(s-ref)/total;sums.append(v);decomp.append(dict(site=site,horizon=h,method=name,scope=scope,points=int(q.loc[(name,scope),'points']),full_points=int(total),weighted_model_MSE=s/total,weighted_daily_MSE=ref/total,delta_MSE=v))
     assert np.isclose(sum(sums),(q.loc[(name,'full'),'SSE']-base)/total,atol=1e-8)
   for month in [4,5,6]:
    stamp=pd.Timestamp(f'2018-{month:02d}-15 10:00',tz=o.tz);j=o.get_indexer([stamp])[0];assert j>=0
    for lead in range(144):
     row={'site':site,'origin':str(o[j]),'selection':'fixed_15th_10am_no_score_selection','lead_minutes':5*(lead+1),'truth':y[j,lead]}
     for name in ['Inverted42','Inverted43','Inverted44','Original_B','Expanded_B','Daily']:row[name]=float(z[name][j,lead])
     cases.append(row)
 pd.DataFrame(summary).to_csv(OUT/'fixed_2018_summary.csv',index=False);pd.DataFrame(decomp).to_csv(OUT/'fixed_2018_mse_decomposition.csv',index=False);pd.DataFrame(cases).to_csv(OUT/'fixed_2018_cases.csv',index=False)
 (OUT/'POINT_ARRAY_AUDIT.json').write_text(json.dumps({'actual_point_metric_rows':len(records),'passed':len(records),'failed':0,'skipped':0,'meaning':'metric/count reductions from saved new-period arrays; not training or independent experiments','records':records},indent=2),encoding='utf8')
 print('Independent new-period point-array reductions:',len(records),'rows; additive MSE identities passed')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--paths',required=True);run(p.parse_args().paths)
